import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2022-07-28","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-07-28","date":"2022-07-28T00:00:00.000Z","updated":"2022-07-29T00:00:00.000Z","tags":["Ceph","RocksDB","Performance Optimization","Tombstone Management","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-07-28.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-07-28.md","lastUpdated":1780460162000}'),s={name:"posts/2022/Ceph_Performance_Meeting_2022-07-28.md"};function n(i,e,l,c,h,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>会议开始时间</strong>: 会议在部分成员未到齐的情况下开始。</li><li><strong>主要议题</strong>: 讨论了优化Ceph中RocksDB设置以减少写放大和改善Tombstone行为的工作进展。</li><li><strong>决定事项</strong>: 决定继续探索在RocksDB中自动触发压缩和刷新的方法，特别是针对删除操作。</li><li><strong>后续行动计划</strong>: 需要进一步研究和测试，以确定最佳的RocksDB设置和删除跟踪机制。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>RocksDB设置优化</strong>: 讨论了如何调整RocksDB设置以减少写放大，特别是在大量删除操作时。提出了通过跟踪每个列族的删除操作来手动触发压缩和刷新的想法。</li><li><strong>Tombstone行为</strong>: 讨论了Tombstone在RocksDB中的影响，特别是在迭代删除周期中的性能问题。提出了通过改进RocksDB的内部机制来减少Tombstone的影响。</li><li><strong>性能和资源管理</strong>: 讨论了如何在不影响系统整体性能的情况下，有效地管理RocksDB的压缩和刷新操作。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>RocksDB优化方案</strong>: 决定继续探索和实施在RocksDB中自动触发压缩和刷新的方法，特别是在删除操作后。</li><li><strong>删除跟踪机制</strong>: 决定开发一种机制来跟踪每个列族的删除操作，并在达到一定阈值后手动触发压缩和刷新。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>进一步研究和测试</strong>: 需要进一步研究和测试，以确定最佳的RocksDB设置和删除跟踪机制。</li><li><strong>代码实现和审查</strong>: 开发团队将开始实现删除跟踪机制，并邀请其他团队成员进行代码审查和测试。</li><li><strong>性能监控和调整</strong>: 在实施新的RocksDB设置后，需要持续监控系统性能，并根据实际情况进行调整。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li><strong>RocksDB内部机制</strong>: 讨论了RocksDB的内部机制，包括压缩和刷新的触发条件，以及如何通过外部代码来控制这些操作。</li><li><strong>性能和资源管理</strong>: 讨论了如何在不影响系统整体性能的情况下，有效地管理RocksDB的压缩和刷新操作。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议讨论了优化RocksDB设置以减少写放大和改善Tombstone行为的工作进展，并决定继续探索和实施在RocksDB中自动触发压缩和刷新的方法。后续需要进一步研究和测试，以确定最佳的RocksDB设置和删除跟踪机制。</p>',13)])])}const u=o(s,[["render",n]]);export{_ as __pageData,u as default};
